@Test
public void testPUT() throws Exception {
    final String container = baseUrl + LdpWebService.PATH + "/test";
    final String put_valid = IOUtils.toString(LdpWebServiceTest.class.getResourceAsStream("/test_update.ttl"), "utf8");
    final String put_invalid = IOUtils.toString(LdpWebServiceTest.class.getResourceAsStream("/test_update_invalid.ttl"), "utf8");
    // Create a resource
    final String resource = RestAssured.given().header("Slug", "PUT").contentType(RDFFormat.TURTLE.getDefaultMIMEType()).body(testResourceTTL.getBytes()).expect().statusCode(201).post(container).getHeader("Location");
    final URI uri = new URIImpl(resource);
    // Check the data is there
    EntityTag etag = EntityTagUtils.parseEntityTag(RestAssured.given().header("Accept", RDFFormat.RDFXML.getDefaultMIMEType()).expect().contentType(RDFFormat.RDFXML.getDefaultMIMEType()).body(SesameMatchers.rdfStringMatches(RDFFormat.RDFXML, resource, SesameMatchers.hasStatement(uri, RDF.TYPE, new URIImpl("http://example.com/Example")), CoreMatchers.not(SesameMatchers.hasStatement(uri, RDFS.LABEL, null)), CoreMatchers.not(SesameMatchers.hasStatement(uri, LDP.contains, uri)))).get(resource).getHeader("ETag"));
    log.debug("ETag for <{}>: {}", resource, etag);
    // Try a Put without if-match header
    RestAssured.given().contentType(RDFFormat.TURTLE.getDefaultMIMEType()).body(put_valid.getBytes()).expect().statusCode(428).put(resource);
    // Try a Put with wrong if-match header
    RestAssured.given().header("If-Match", new EntityTag("invalid").toString()).contentType(RDFFormat.TURTLE.getDefaultMIMEType()).body(put_valid.getBytes()).expect().statusCode(412).put(resource);
    // Try a Put
    RestAssured.given().header("If-Match", etag.toString()).contentType(RDFFormat.TURTLE.getDefaultMIMEType()).body(put_valid.getBytes()).expect().statusCode(200).put(resource);
    // Check the new data is there
    etag = EntityTagUtils.parseEntityTag(RestAssured.given().header("Accept", RDFFormat.RDFXML.getDefaultMIMEType()).expect().contentType(RDFFormat.RDFXML.getDefaultMIMEType()).body(SesameMatchers.rdfStringMatches(RDFFormat.RDFXML, resource, SesameMatchers.hasStatement(uri, RDF.TYPE, new URIImpl("http://example.com/Example")), SesameMatchers.hasStatement(uri, RDFS.LABEL, null), CoreMatchers.not(SesameMatchers.hasStatement(uri, LDP.contains, uri)))).get(resource).header("ETag"));
    // Try an invalid PUT (server-controlled property)
    // Try a Put
    RestAssured.given().header("If-Match", etag.toString()).contentType(RDFFormat.TURTLE.getDefaultMIMEType()).body(put_invalid.getBytes()).expect().statusCode(409).put(resource);
    // Check the data is still there
    RestAssured.given().header("Accept", RDFFormat.RDFXML.getDefaultMIMEType()).expect().contentType(RDFFormat.RDFXML.getDefaultMIMEType()).header("ETag", HeaderMatchers.hasEntityTag(etag)).body(SesameMatchers.rdfStringMatches(RDFFormat.RDFXML, resource, SesameMatchers.hasStatement(uri, RDF.TYPE, new URIImpl("http://example.com/Example")), SesameMatchers.hasStatement(uri, RDFS.LABEL, null), CoreMatchers.not(SesameMatchers.hasStatement(uri, LDP.contains, uri)))).get(resource);
}

